function Lvl1Manager:__init()
    self.controller = nil
    self.co = nil   -- 发送携程请求
    self.loaders = {}
end


function Lvl1Manager:__delete()
    self.loaders = nil
    self.co = nil
end



function Lvl1Manager:Awake()
    KTool.SetActive(self.controller.gameObject, true);
end

function Lvl1Manager:Start()
    KTool.SetActive(self.controller.gameObject, true);
    DreamSpaceLuaUtils.StopCoroutine( self.co )
    self.co = cs_coroutine.start(self.DelayInit, self)
end

function Lvl1Manager:DelayInit() 

    self.isInit = false

    assert( self.localEventSystem )
    assert( self.piecesCollectionBH )
    assert( self.questLvl1BH )
    assert( self.initPos )

    assert( self.startStoryBH )
    self.startStory = DreamSpaceLuaUtils.GetLuaScr(self.startStoryBH.gameObject, "Game.DreamSpace.Level1.Story.DreamSpace_StartStory" )
    assert( self.startStory )
   
    self.params = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( self.params )

    
    -- ================================ 
    InputManager.Init() -- 重置, 必须在 装配 角色控制器 之前!!!  否则角色的初始朝向会被 InputManager 里的残余值修改;

    -- 正式装配 角色控制器:
    cs_coroutine.yield_return( RoleControllerLoader.AssembleRole({
        switchablePlayerPrefabPath  = "DreamSpace/Gameplay/SwitchablePlayeForLua.prefab",
        humanPrefabPath             = "Arts/Prefab_human/103008_human.prefab",
        ---
        initPos = self.initPos.position,
        initRoleDir = self.initPos.forward,
        initLookDir = self.initPos.forward,
        initHumanScale = Vector3.one,
        humanCapsuleRadius = 0.5,
        isCat = false, 
        isIgnoreJumpHint = false,
        isIgnoreHuman180TurnBack = false,
        isUsePiecesCollector = true,
    }))
    ---
    RoleControllerLoader.ClearLoaders() 


    ---------------------- 
    self.levelID = LuaParametersReader.Read( self.params, "levelID", LuaParametersReader.Type.Int )
    print( "levelID = " .. self.levelID )

    -- ---:
    self.piecesCollection = DreamSpaceLuaUtils.GetLuaScr(self.piecesCollectionBH.gameObject, "Game.DreamSpace.PiecesCollection.PiecesCollection" )
    assert( self.piecesCollection )
    self.piecesCollection:SelfInit( self.levelID )

    ---
    KTool.SetActive( self.localEventSystem.gameObject, false )

    self.globalsInDreamSpace = GlobalsInDreamSpace.Instance
    assert( self.globalsInDreamSpace )


    -- =================================================================================== -- 

    -- 强制设置 白塔的 初始帧率:
    DreamSpaceStates.cachedFrameRate = Application.targetFrameRate
    Application.targetFrameRate = DreamSpaceLuaUtils.IsReallyPCPlatform() and DreamSpaceStates.recommendedFrameRateForPC or DreamSpaceStates.recommendedFrameRateForMobile

    -- 初始化 pc ui 互斥子界面:
    DreamSpaceStates.currentOpenPanelTypeInPC = DreamSpaceStates.CurrentOpenPanelTypeInPC.None
    DreamSpaceStates.IsSubPanelFreeInPC_Reset()
    DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Lock ) -- PC 版 禁止打开 ui 子界面 

    ----
    DreamSpaceStates.InitInputLock() -- 初始化
    DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Lock ) -- 希望禁止玩家输入

    GearHint.InitStatics() -- 初始化
    InspectHint.InitStatics() -- 初始化
 

    DreamSpaceSounds.StopAll() -- 停止外部一切音乐
    DreamSpaceSounds.Play( DreamSpaceSounds.ambience.explore )


    coroutine.yield(Yielders.EndOfFrame)

    -- 隐藏 DreamSpace UI:
    local RoleControllerRootCanvasMgr = import('Game.DreamSpace.UI.RoleControllerRootCanvasMgr'):GetInstance()
    RoleControllerRootCanvasMgr:ShowOrHide( false  ) -- hide


    -- ================
    -- 等待 UI 加载页面自己被销毁:
    cs_coroutine.yield_return( self:WaitUILoadPanelFinish() ) 


    -------- 白塔游戏开场,  动画剧情演绎 ----------
    cs_coroutine.yield_return( self.startStory:Play() )


    -- 显示 DreamSpace UI:
    RoleControllerRootCanvasMgr:ShowOrHide( true  ) -- show

    DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- 解除禁止:玩家输入
    DreamSpaceStates.subPanelFreesInPC.mainProcess = true   -- PC 版 允许打开 ui 子界面 
    DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- PC 版 允许打开 ui 子界面 

    ---:
    self.questLvl1 = DreamSpaceLuaUtils.GetLuaScr(self.questLvl1BH.gameObject, "Game.DreamSpace.Level1.Quest.QuestLvl1" )
    assert( self.questLvl1 )
    self.questLvl1:SelfInit( self.levelID, self.piecesCollection )


    -- todo: 有空找个更好的位置放下述代码:
    self:RegisterInputFunc()
    -- ----------------
    self.isInit = true
end




-- ===============================================================


function Lvl1Manager:OnDestroy()

    -- 删除 ui canvas:
    local RoleControllerRootCanvasMgr = import('Game.DreamSpace.UI.RoleControllerRootCanvasMgr'):GetInstance()
    RoleControllerRootCanvasMgr:CheckAndRemove()

    ---
    DreamSpaceLuaUtils.StopCoroutine( self.co )
    self.co = nil

    if not isNull(self.globalsInDreamSpace) and not isNull(self.globalsInDreamSpace.gameObject) then
        Object.Destroy( self.globalsInDreamSpace.gameObject )
    end

    self:UnRegisterInputFunc()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



function Lvl1Manager:WaitUILoadPanelFinish()

    local go = GameObject.Find("LoadingPanel")
    if isNotNull(go) then        
        ---@type UILoadingPanel
        local loadingUI = DreamSpaceLuaUtils.GetLuaScr(go, "Game.Behaviours.UILoadingPanel" )

        -- 等待 进度条页面关闭
        while true do
            if isNull(go) then 
                return
            end 
            coroutine.yield(Yielders.EndOfFrame)
        end 
    else 
        printError("koko - 没能找到 LoadingPanel ")
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 2 ))
    end
end

function Lvl1Manager:RegisterInputFunc()
    local KeyboardInputMap = KeyboardInputMap:GetInstance()

    KeyboardInputMap:RegisterInput(KeyboardInfo.InteractiveKey, GearHint.TriggerGearInPCMode)
    KeyboardInputMap:RegisterInput(KeyboardInfo.InspectKey, InspectHint.TriggerInspectInPCMode)

    local playerInputSwitcher = GlobalsInDreamSpace.FindComponent("playerInputSwitcher")
    local CursorLockMode = CS.UnityEngine.CursorLockMode
    local Cursor = CS.UnityEngine.Cursor
    if playerInputSwitcher then
        KeyboardInputMap:RegisterInput(KeyboardInfo.JumpKey, function ()
            print("jump")
            playerInputSwitcher.Env:OnJump()
            Cursor.lockState = CursorLockMode.Locked
        end)

        -- KeyboardInputMap:RegisterInput(KeyboardInfo.SwitchKey, function ()
        --     print("switch")
        --     playerInputSwitcher.Env:OnSwitch()
        -- end)

        -- KeyboardInputMap:RegisterInput(KeyboardInfo.AttackKey, function ()
        --     print("attack")
        --     playerInputSwitcher.Env:OnAttack()
        -- end)

    end
    
end

function Lvl1Manager:UnRegisterInputFunc()
    local KeyboardInputMap = KeyboardInputMap:GetInstance()
    KeyboardInputMap:UnRegisterInput(KeyboardInfo.InteractiveKey)
    KeyboardInputMap:UnRegisterInput(KeyboardInfo.InspectKey)
    ---
    -- KeyboardInputMap:UnRegisterInput(KeyboardInfo.SwitchKey)
    -- KeyboardInputMap:UnRegisterInput(KeyboardInfo.AttackKey)
    KeyboardInputMap:UnRegisterInput(KeyboardInfo.JumpKey)
end

return Lvl1Manager
